import numpy as np


class QuantumNeuralNetwork:
    """Quantum neural network with multiple layers of parameterized gates."""

    def __init__(self, n_qubits, n_layers, n_inputs):
        self.n_qubits = n_qubits
        self.n_layers = n_layers
        self.n_inputs = n_inputs
        self.dim = 2 ** n_qubits

        self.n_data_params = n_inputs
        self.n_var_params = n_layers * n_qubits * 3
        self.n_params = self.n_data_params + self.n_var_params
        self.params = np.random.randn(self.n_params) * 0.1

    def _ry(self, theta):
        return np.array([
            [np.cos(theta / 2), -np.sin(theta / 2)],
            [np.sin(theta / 2), np.cos(theta / 2)]
        ], dtype=complex)

    def _rz(self, theta):
        return np.array([
            [np.exp(-1j * theta / 2), 0],
            [0, np.exp(1j * theta / 2)]
        ], dtype=complex)

    def _single_qubit_gate(self, gate, qubit):
        full_op = np.array([[1]], dtype=complex)
        for q in range(self.n_qubits):
            if q == qubit:
                full_op = np.kron(full_op, gate)
            else:
                full_op = np.kron(full_op, np.eye(2, dtype=complex))
        return full_op

    def _apply_cnot(self, state, control, target):
        cnot = np.zeros((self.dim, self.dim), dtype=complex)
        for i in range(self.dim):
            control_bit = (i >> (self.n_qubits - 1 - control)) & 1
            if control_bit == 1:
                j = i ^ (1 << (self.n_qubits - 1 - target))
                cnot[j, i] = 1.0
            else:
                cnot[i, i] = 1.0
        return cnot @ state

    def encode_input(self, state, x):
        for q in range(min(self.n_qubits, len(x))):
            ry_gate = self._ry(x[q] * np.pi)
            full_op = self._single_qubit_gate(ry_gate, q)
            state = full_op @ state
        return state

    def variational_layer(self, state, params, layer_idx):
        base_idx = self.n_data_params + layer_idx * self.n_qubits * 3

        for q in range(self.n_qubits):
            ry1 = self._ry(params[base_idx + q * 3])
            state = self._single_qubit_gate(ry1, q) @ state

            rz = self._rz(params[base_idx + q * 3 + 1])
            state = self._single_qubit_gate(rz, q) @ state

            ry2 = self._ry(params[base_idx + q * 3 + 2])
            state = self._single_qubit_gate(ry2, q) @ state

        for q in range(self.n_qubits):
            target = (q + 1) % self.n_qubits
            state = self._apply_cnot(state, q, target)

        return state

    def forward(self, x, params=None):
        if params is None:
            params = self.params

        state = np.zeros(self.dim, dtype=complex)
        state[0] = 1.0
        state = self.encode_input(state, x[:self.n_inputs])

        for layer in range(self.n_layers):
            state = self.variational_layer(state, params, layer)

        return state

    def predict(self, x, params=None):
        state = self.forward(x, params)

        z_operator = np.zeros((self.dim, self.dim), dtype=complex)
        for i in range(self.dim):
            first_bit = (i >> (self.n_qubits - 1)) & 1
            z_operator[i, i] = 1.0 if first_bit == 0 else -1.0

        expectation = np.real(state.conj() @ (z_operator @ state))
        return (expectation + 1) / 2

    def compute_loss(self, x, y, params=None):
        pred = self.predict(x, params)
        pred = np.clip(pred, 1e-7, 1 - 1e-7)
        return -(y * np.log(pred) + (1 - y) * np.log(1 - pred))

    def train_step(self, X, y, lr=0.01, shift=np.pi/2):
        total_loss = 0.0
        grads = np.zeros(self.n_params)

        for i in range(len(X)):
            total_loss += self.compute_loss(X[i], y[i])

            for p in range(self.n_params):
                params_plus = self.params.copy()
                params_plus[p] += shift
                params_minus = self.params.copy()
                params_minus[p] -= shift

                f_plus = self.compute_loss(X[i], y[i], params_plus)
                f_minus = self.compute_loss(X[i], y[i], params_minus)
                grads[p] += (f_plus - f_minus) / 2

        grads /= len(X)
        self.params -= lr * grads
        return total_loss / len(X)


if __name__ == "__main__":
    np.random.seed(42)
    qnn = QuantumNeuralNetwork(n_qubits=2, n_layers=2, n_inputs=2)

    X = np.array([[0.1, 0.2], [0.8, 0.9], [0.2, 0.1], [0.9, 0.8]])
    y = np.array([0.0, 1.0, 0.0, 1.0])

    for epoch in range(5):
        loss = qnn.train_step(X, y, lr=0.1)
        print(f"Epoch {epoch}: loss={loss:.4f}")

    for i in range(len(X)):
        pred = qnn.predict(X[i])
        print(f"  x={X[i]}, pred={pred:.3f}, target={y[i]}")
